#!/usr/bin/env bash
# Write the endpoints file the agent layer reads instead of hard-coding URLs.
. "$(dirname "$0")/lib.sh"
cat > "$WORK/endpoints.env" <<E
# Core1 endpoints (host side). Generated by scripts/endpoints.sh; do not edit.
CORE1_ROOT=$ROOT
CORE1_CLUSTER=$CLUSTER_NAME
CORE1_KUBECONFIG_ADMIN=$KUBECONFIG
CORE1_KUBECONFIG_AGENT=$KUBE_DIR/agent-readonly.yaml
CORE1_CONFIG_REPO=$CONFIG_REPO
CORE1_NS_APP=$NS_APP
CORE1_NS_OBS=$NS_OBS
CORE1_NS_SYS=$NS_SYS
CORE1_PROMETHEUS_URL=$PROM_URL
CORE1_ALERTMANAGER_URL=$ALERTMANAGER_URL
CORE1_LOKI_URL=$LOKI_URL
CORE1_GRAFANA_URL=$GRAFANA_URL
CORE1_GRAFANA_USER=admin
CORE1_GRAFANA_PASSWORD=$GRAFANA_ADMIN_PASSWORD
CORE1_GATEWAY_URL=$GATEWAY_URL
CORE1_ALERT_SINK_URL=$ALERT_SINK_URL
CORE1_ALERT_WEBHOOK_URL=$ALERT_WEBHOOK_URL
CORE1_HOST_FROM_CLUSTER=host.k3d.internal
E
"$PYTHON" - "$WORK/endpoints.env" "$WORK/endpoints.json" <<'PY'
import json, sys
d = {}
for line in open(sys.argv[1]):
    line = line.strip()
    if line and not line.startswith("#") and "=" in line:
        k, v = line.split("=", 1); d[k] = v
json.dump(d, open(sys.argv[2], "w"), indent=2)
PY
chmod 600 "$WORK/endpoints.env" "$WORK/endpoints.json"
log "endpoints written: $WORK/endpoints.env, $WORK/endpoints.json"
